            aIngress = (RotL64(aFuseLaneB[((aIndex + 17598U)) & S_BLOCK1], 28U) ^ RotL64(aWaterLaneD[((aIndex + 20363U)) & S_BLOCK1], 43U));
            aIngress ^= (RotL64(aFireLaneA[((aIndex + 17529U)) & S_BLOCK1], 19U) ^ RotL64(pSnowLaneA[((S_BLOCK1 - aIndex + 21945U)) & S_BLOCK1], 11U));
            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 22768U)) & S_BLOCK1], 42U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 17143U)) & S_BLOCK1], 23U));
            aCross ^= RotL64(pSnowLaneC[((S_BLOCK1 - aIndex + 19074U)) & S_BLOCK1], 13U);
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCarry, 6U) + RotL64(aIngress, 21U)) + (RotL64(aPrevious, 57U) ^ RotL64(aCross, 35U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = (aWandererF + RotL64(aScatter, 51U)) + 0x2ACC48E21DA08FCBULL;
            aOrbiterC = (aWandererA + RotL64(aIngress, 43U)) + 0x5021CC3BA4FDABA9ULL;
            aOrbiterA = (((aWandererD + RotL64(aPrevious, 34U)) + RotL64(aCarry, 27U)) + 0x91963A82C5F86D0FULL) + aTwistOrbiterAssignSaltC[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aCross, 27U)) + 0x6AE1A910506BB9DFULL;
            aOrbiterB = ((aWandererK + RotL64(aIngress, 57U)) + RotL64(aCarry, 41U)) + 0x21A2965186D7C2E7ULL;
            aOrbiterF = (aWandererC + RotL64(aPrevious, 19U)) + 0x560D32B296A0554FULL;
            aOrbiterH = (((aWandererG + RotL64(aScatter, 11U)) + RotL64(aCarry, 5U)) + 0x1CF0B23C2705F66FULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 27U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x12EDE3E8DA1D374FULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xD7D2D126B1A3AD79ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA06377170605BA67ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xABD0B9E49E3D7D7AULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x5D3BACAE899F7A3CULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1E96A2229C3ED65FULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x26A052F288B9247FULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0x4345EB6335FBA604ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 29U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xB0AA5FB0432B2C35ULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x39BA2205CEAEAE3EULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0xDC9D0819B13ABACFULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 17U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x6D86247053D502AFULL), 35U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0xD5B9A91C9C93916FULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x123C5BBDB9F021C6ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xB05ACFE7A3FB6B15ULL), 11U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterA) + 0xBF4B6AF3CFE16A53ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 12U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x0FE6DCBE14ED670DULL;
            aOrbiterB = RotL64((aOrbiterB * 0x44D2BE0DB150B1DBULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xF8E13CA2242932DEULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x10CB3405B2069703ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xEFB0DB6E288494E7ULL), 41U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterF, 37U);
            aIngress = aIngress + (RotL64(aOrbiterA, 29U) ^ aOrbiterC);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterB, 19U));
            aIngress = aIngress + RotL64(aOrbiterH, 43U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF + (((RotL64(aCross, 57U) + aOrbiterH) + RotL64(aOrbiterJ, 56U)) + RotL64(aCarry, 37U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 43U) + RotL64(aOrbiterB, 3U)) + aOrbiterF);
            aWandererG = aWandererG + ((RotL64(aScatter, 51U) + RotL64(aOrbiterF, 41U)) + aOrbiterC);
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 27U) + RotL64(aOrbiterA, 19U)) + aOrbiterC) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 21U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aScatter, 11U) + aOrbiterJ) + RotL64(aOrbiterC, 11U)) + RotL64(aCarry, 51U));
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 20U) + aOrbiterI) + RotL64(aOrbiterC, 47U));
            aWandererC = aWandererC + (((RotL64(aIngress, 3U) + aOrbiterF) + RotL64(aOrbiterJ, 27U)) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 14U)) & S_SALT1]);
