            aOrbiterH = ((aWandererI + RotL64(aScatter, 27U)) + 0xCBEDAD3E284CC96EULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterJ = ((aWandererF + RotL64(aPrevious, 5U)) + 0x8CE4FAA73C049C6AULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterK = (aWandererC + RotL64(aIngress, 53U)) + 0x98C2E14074456372ULL;
            aOrbiterD = (aWandererB + RotL64(aScatter, 47U)) + 0x9E9AA41051E1EE4CULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x19F36C07E4F93F8FULL;
