            aOrbiterF = RotL64((aOrbiterF * 0xC233966E3D5F05CFULL), 53U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0xFB2A07B166E39BA5ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 20U)) & S_SALT1];
