            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0xF2450BA5DC7E1FC1ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0xDB34092212AFEA44ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xAE51C1B034B8817DULL), 47U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x731D333C7A0FAF28ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x2A3DBBEF05D3D2C6ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7F4DD0D549EAD1C3ULL), 23U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x8A6553514A7277A1ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x5C7E6AD6FCE04AEAULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x3CA8EE4A20E3766DULL), 5U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x7E14A864F9A7D5D7ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0x995422B37E84AF7BULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x62E3EFA91BA3B117ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xDE032D27F14D297EULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xB0B8837F103F04C3ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xFA91597EA0F0EC71ULL), 13U);
            //
            aIngress = RotL64(aOrbiterH, 41U) ^ aOrbiterD;
            aIngress = aIngress + (RotL64(aOrbiterK, 21U) ^ aOrbiterB);
            aIngress = aIngress + (RotL64(aOrbiterI, 47U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterF, 53U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aScatter, 47U) + RotL64(aOrbiterJ, 11U)) + aOrbiterK);
            aWandererH = aWandererH + ((((RotL64(aCross, 53U) + RotL64(aOrbiterF, 3U)) + aOrbiterD) + RotL64(aCarry, 5U)) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterH, 29U)) + aOrbiterJ) + aKeyRotateWandererUpdateSaltA[((aIndex + 23U)) & S_SALT1]);
            aWandererA = aWandererA + (((RotL64(aPrevious, 19U) + RotL64(aOrbiterF, 60U)) + aOrbiterH) + RotL64(aCarry, 41U));
            aWandererI = aWandererI ^ ((RotL64(aScatter, 4U) + RotL64(aOrbiterI, 41U)) + aOrbiterF);
            aWandererF = aWandererF + ((RotL64(aCross, 37U) + aOrbiterF) + RotL64(aOrbiterB, 35U));
