            aIngress = (RotL64(aShadowLaneC[((aIndex + 26383U)) & S_BLOCK1], 35U) ^ RotL64(aShadowLaneA[((aIndex + 27493U)) & S_BLOCK1], 11U));
            aIngress ^= (RotL64(aSoilLaneD[((aIndex + 25079U)) & S_BLOCK1], 54U) ^ RotL64(aLightningLaneA[((aIndex + 24607U)) & S_BLOCK1], 43U));
