            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 35U) + RotL64(aCarry, 5U)) ^ (RotL64(aCross, 18U) + RotL64(aIngress, 57U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterC = ((aWandererC + RotL64(aIngress, 27U)) + RotL64(aCarry, 27U)) + 0xF8276CEE1AF6D2B2ULL;
            aOrbiterI = ((aWandererD + RotL64(aPrevious, 5U)) + RotL64(aCarry, 41U)) + 0x2C9A1BABF114B998ULL;
            aOrbiterJ = (aWandererG + RotL64(aCross, 21U)) + 0xD328A4262D2219A8ULL;
            aOrbiterG = ((aWandererA + RotL64(aScatter, 11U)) + 0xBE10844DF40824CEULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = (aWandererK + RotL64(aIngress, 53U)) + 0x16EE9966D03510D5ULL;
            aOrbiterB = ((aWandererF + RotL64(aScatter, 37U)) + 0x76329FCD20462E43ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 27U)) & S_SALT1];
            aOrbiterE = ((aWandererH + RotL64(aCross, 60U)) + RotL64(aCarry, 3U)) + 0x64C345E77815D5B4ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x25BD49EAE4F1A9FBULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x28273DA06146FD22ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAEC0A0469D02443DULL), 21U);
