            //
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 11U) + aOrbiterB) + RotL64(aOrbiterH, 47U)) + aKeyRotateWandererUpdateSaltF[((aIndex + 13U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aCross, 51U) + aOrbiterE) + RotL64(aOrbiterG, 35U)) + RotL64(aCarry, 41U));
