            aCross = (RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 3682U)) & S_BLOCK1], 29U) ^ RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 7247U)) & S_BLOCK1], 13U));
            aCross ^= (RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 203U)) & S_BLOCK1], 39U) ^ RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 5414U)) & S_BLOCK1], 58U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCarry, 11U) ^ RotL64(aIngress, 57U)) + (RotL64(aCross, 40U) ^ RotL64(aPrevious, 27U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterE = (aWandererH + RotL64(aIngress, 44U)) + 0x32F71C66BAF1755AULL;
            aOrbiterG = (((aWandererI + RotL64(aScatter, 21U)) + RotL64(aCarry, 23U)) + 0xBEC73F6C9B498329ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aPrevious, 39U)) + RotL64(aCarry, 35U)) + 0xE77A31DC1F34A2B1ULL;
            aOrbiterK = (aWandererD + RotL64(aCross, 13U)) + 0x12D2EB9E87948853ULL;
            aOrbiterJ = (aWandererF + RotL64(aScatter, 48U)) + 0xA7776D0D530463F4ULL;
            aOrbiterA = (aWandererB + RotL64(aPrevious, 53U)) + 0x81062EA8CF9E51AFULL;
