            aWandererI = aWandererI ^ ((RotL64(aScatter, 27U) + RotL64(aOrbiterB, 35U)) + aOrbiterG);
            aWandererG = aWandererG + (((RotL64(aIngress, 19U) + RotL64(aOrbiterJ, 19U)) + aOrbiterI) + RotL64(aCarry, 29U));
