            //
            aIngress = (RotL64(aWindLaneA[((aIndex + 2120U)) & S_BLOCK1], 37U) ^ RotL64(aWindLaneB[((aIndex + 5727U)) & S_BLOCK1], 27U));
            aIngress ^= (RotL64(aMagmaLaneD[((aIndex + 1184U)) & S_BLOCK1], 51U) ^ RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 2407U)) & S_BLOCK1], 4U));
