            aOrbiterE = ((aWandererD + RotL64(aIngress, 20U)) + 0x351AEAB679CE83A9ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = ((aWandererH + RotL64(aPrevious, 57U)) + RotL64(aCarry, 57U)) + 0x02CC987E0771142AULL;
            aOrbiterA = (aWandererK + RotL64(aCross, 39U)) + 0x691E5927241EDA66ULL;
            aOrbiterK = (aWandererA + RotL64(aScatter, 37U)) + 0xB7C8C506F74952EBULL;
            aOrbiterG = ((aWandererF + RotL64(aCross, 29U)) + RotL64(aCarry, 29U)) + 0x67E6FE4364971AA9ULL;
            aOrbiterH = (aWandererE + RotL64(aIngress, 27U)) + 0x2E71D5E50AB9EEABULL;
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 14U)) + 0xC09155CB7657B2C2ULL;
