            aOrbiterB = (aWandererJ + RotL64(aPrevious, 41U)) + 0x3A34356DB50F5E7FULL;
            aOrbiterI = ((aWandererG + RotL64(aIngress, 11U)) + RotL64(aCarry, 37U)) + 0xC734EDCE5785FB1FULL;
            aOrbiterC = (aWandererC + RotL64(aCross, 47U)) + 0xD5292E0F7828AAF1ULL;
