            aOrbiterD = RotL64((aOrbiterD * 0x8C5CB149C8C2C1B5ULL), 5U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xACB9937E4B297E3BULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xAF5A2593036EBF65ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x79DEF21AA6B6454DULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x0ACA1613A6BD0D5FULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
