            aWandererA = aWandererA + (((RotL64(aIngress, 5U) + aOrbiterK) + RotL64(aOrbiterG, 34U)) + RotL64(aCarry, 11U));
            aWandererF = aWandererF ^ ((RotL64(aCross, 43U) + aOrbiterA) + RotL64(aOrbiterC, 27U));
            //
            aCarry = aCarry + (RotL64(aWandererI, 39U) ^ aWandererA);
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererF, 10U));
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererH, 57U));
