            aScatter = (RotL64(aPrevious, 13U) + RotL64(aCross, 58U)) ^ (RotL64(aCarry, 29U) ^ RotL64(aIngress, 43U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterI = ((aWandererJ + RotL64(aPrevious, 37U)) + 0x44D2095035265277ULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 3U)) & S_SALT1];
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 57U)) + 0x0FADDEE9D1B7BE29ULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 17U)) & S_SALT1];
