            aOrbiterC = ((aWandererF + RotL64(aIngress, 26U)) + RotL64(aCarry, 47U)) + 0xDC23928E8C9BADEFULL;
            aOrbiterH = (aWandererC + RotL64(aCross, 39U)) + 0x1F6420DA61D430AFULL;
