            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xD654286A0C832AF6ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xF23745779FA153B8ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x7C2AE2C1AC82C723ULL), 21U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x0932F9BCD9B4C613ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x4E15AE2A4E3EDC30ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD70AF5511E122EE9ULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xD8D74AB2B4B79745ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x695D104828378D88ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x46701EDED32BF347ULL), 41U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xCCDAD18F5ADC3AB1ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xDBD4FEA4549D5731ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x41286C4E7C8DCB35ULL), 43U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x8C92F91D32B4920BULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x68D1672C7E62BAC8ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x3559BE5EEA3999C5ULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x1413B7B9445930E4ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0x3B70893A243C5CDAULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 13U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xED4AFB38CD852079ULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x8D7C72FB26635330ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterG) ^ 0xD15046F6B9625EF3ULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 19U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x9D0830BF0ED2121FULL), 27U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x226CE9C498692CD6ULL;
